-- Standard chart frozen from Cliente Piloto QA (c56bc5df-c807-4deb-83f8-fbb4751be613).
-- Read-only extraction 2026-10-20. Exact 2508 rows, including both HEART auxiliaries.
-- No balances, journal entries, parties, users or source database IDs are copied.
-- Apply ONLY through the authorized desarrollo -> develop -> main release process.
create schema apexos_accounting_private;
revoke all on schema apexos_accounting_private from public;

create table apexos_accounting_private.standard_chart (
  code text primary key,
  name text not null,
  type text not null,
  parent_code text references apexos_accounting_private.standard_chart(code) deferrable initially deferred,
  level integer not null check (level between 1 and 5),
  allows_tx boolean not null,
  active boolean not null
);
alter table apexos_accounting_private.standard_chart enable row level security;
revoke all on apexos_accounting_private.standard_chart from public;

