-- Invoker only: callable by the migration/backend database owner, never exposed as RPC.
create function apexos_accounting_private.ensure_standard_chart(target_id text)
returns jsonb language plpgsql security invoker set search_path = ''
as $function$
declare
  current_level integer;
  inserted_count integer := 0;
  repaired_count integer := 0;
  affected integer;
begin
  if target_id is null or not (
    exists(select 1 from public."Tenant" where id = target_id)
    or exists(select 1 from public.companies where id::text = target_id)
  ) then
    raise exception 'STANDARD_CHART_TARGET_REQUIRED';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('standard-chart:' || target_id, 0));

  -- Incompatible existing accounts block the whole transaction. Never recode postings.
  if exists (
    select 1 from public."Account" a
    join apexos_accounting_private.standard_chart s on s.code = a.code
    left join public."Account" p on p.id = a.parent_id
    where a.tenant_id = target_id and (
      a.type is distinct from s.type
      or (a.parent_id is not null and (p.tenant_id is distinct from target_id or p.code is distinct from s.parent_code))
    )
  ) then
    raise exception 'STANDARD_CHART_CONFLICT';
  end if;

  for current_level in 1..5 loop
    insert into public."Account" (tenant_id, code, name, type, parent_id, level, allows_tx, active)
    select target_id, s.code, s.name, s.type, p.id, s.level, s.allows_tx, s.active
    from apexos_accounting_private.standard_chart s
    left join public."Account" p on p.tenant_id = target_id and p.code = s.parent_code
    where s.level = current_level
    on conflict (tenant_id, code) do nothing;
    get diagnostics affected = row_count;
    inserted_count := inserted_count + affected;
  end loop;

  -- Repair only absent parent links and hierarchy depth. Preserve identity, business fields,
  -- active status, allows_tx and every existing ledger reference.
  update public."Account" a set parent_id = p.id, level = s.level
  from apexos_accounting_private.standard_chart s
  join public."Account" p on p.tenant_id = target_id and p.code = s.parent_code
  where a.tenant_id = target_id and a.code = s.code
    and (a.parent_id is null or a.level is distinct from s.level);
  get diagnostics repaired_count = row_count;
  update public."Account" a set level = s.level
  from apexos_accounting_private.standard_chart s
  where a.tenant_id = target_id and a.code = s.code and s.parent_code is null
    and a.level is distinct from s.level;

  if exists (
    select 1 from apexos_accounting_private.standard_chart s
    left join public."Account" a on a.tenant_id = target_id and a.code = s.code
    left join public."Account" p on p.id = a.parent_id and p.tenant_id = target_id
    where a.id is null or p.code is distinct from s.parent_code
  ) then raise exception 'STANDARD_CHART_INCOMPLETE'; end if;
  return pg_catalog.jsonb_build_object('version', 'piloto-qa-20261020', 'created', inserted_count, 'linked', repaired_count);
end
$function$;
revoke all on function apexos_accounting_private.ensure_standard_chart(text) from public;

-- Definer is needed only for the insert trigger: its target is NEW.id, never a
-- caller-supplied tenant parameter. Existing table authorization/RLS still gates INSERT.
create function apexos_accounting_private.seed_new_company_chart()
returns trigger language plpgsql security definer set search_path = ''
as $function$
begin
  perform apexos_accounting_private.ensure_standard_chart(new.id::text);
  return new;
end
$function$;
revoke all on function apexos_accounting_private.seed_new_company_chart() from public;

create trigger seed_standard_chart_company after insert on public.companies
for each row execute function apexos_accounting_private.seed_new_company_chart();
create trigger seed_standard_chart_tenant after insert on public."Tenant"
for each row execute function apexos_accounting_private.seed_new_company_chart();

-- Both creation paths and preexisting companies are covered. All work is transactional:
-- a conflict aborts the migration; no deletes or changes to journal entries occur.
do $backfill$
declare company record;
begin
  for company in
    select id::text as id from public.companies
    union select id from public."Tenant"
    order by id
  loop
    perform apexos_accounting_private.ensure_standard_chart(company.id);
  end loop;
end
$backfill$;

